class BerryField:
    def __init__(self,newmap,bears,tourists):
        self.L = newmap
        self.sumnum = 0
        self.bears =[]
        self.tourists = []
        self.bears1 = bears

        print(bears[0].get())

        for i in bears:
            y,x,d,b,sleep = i.get()
            self.bears.append((y,x))
        for i in tourists:
            y,x = i.get()
            self.tourists.append((y,x))
        for i in range(len(self.L)):
            for j in range(len(self.L[i])):
                if type(self.L[i][j]) == int:
                    self.sumnum +=int(self.L[i][j])

        '''






    def __str__(self):

        for i in range(len(self.L)):
            for j in range(len(self.L[i])):
                if (i,j) in self.bears and (i,j) in self.tourists:
                    print("   X",end="")
                elif (i,j) in self.bears:
                    print("   B",end="")
                elif(i,j) in self.tourists:
                    print("   T",end="")
                else:
                    print("{:>4}".format(self.L[i][j]),end="")

            print()
        return ""
    '''

    def printAll(self):
        print("Field has",self.sumnum,"berries.")
        for i in range(len(self.L)):
            for j in range(len(self.L[i])):
                if (i,j) in self.bears and (i,j) in self.tourists:
                    print("   X",end="")
                elif (i,j) in self.bears:
                    print("   B",end="")
                elif(i,j) in self.tourists:
                    print("   T",end="")
                else:
                    print("{:>4}".format(self.L[i][j]),end="")

            print()
        return ''




    def printBerry(self):

        for i in range(len(self.L)):
            for j in range(len(self.L[i])):
                print("{:>4}".format(self.L[i][j]),end="")
            print()
        return ""

    def grow(self):
        for i in range(len(self.L)):
            for j in range(len(self.L[i])):
                if self.L[i][j]<10:
                    self.L[i][j] +=1

#h (N), South (S), East (E), West (W), NorthEast (NE), NorthWest
(NW),SouthEast (SE), or SouthWest (SW)
    def updateByBear(self):
        for i in self.bears1:
            y,x,d,b,sleep = i.get()
            while b <30:
                if y<0
                b+=self.L[y][x]
                if d == "N":
                        y = y-1
                elif d=="S":
                        y =y+1
                elif d=="E":
                    x = x+1
                elif d=="W":
                    x = x-1
                elif d=="NE":
                    y = y-1
                    x = x+1
                elif d=="NW":
                    y = y-1
                    x = x-1
                elif d=="SE":
                    y =y+1
                    x = x+1
                elif d=="SW":
                    y =y+1
                    x = x-1
class Bear:
    def __init__(self,y,x,d):
        #self.active = active
        #self.reverse = reverse
        self.y = y
        self.x = x
        self.d = d
        self.b = 0
        self.sleep = False


    def __str__(self):
        print(str(self.y),str(self.x),str(self.d))
        return ""


    def update(self,y,x):
        self.y = y
        self.x = x

    def get(self):
        return self.y, self.x, self.d,self.b,self.sleep

    def activeBears(self):
        s = "Bear at ({},{}) moving {}".format(self.y,self.x,self.d)
        return s

    def leaveBear(self):
        s = "Bear at ({},{}) moving {} - Left the
Field".format(self.y,self.x,self.d)

class Tourist:
    def __init__(self,y,x,cnt=0):
        self.y = y
        self.x = x
        self.cnt = cnt
        '''
