# -*- coding: utf-8 -*-
"""
Created on Tue Dec 10 20:34:04 2024

@author: skk12
"""




import json
import BerryField
import Bear
import Tourist
fn = input("Enter the json file name for the simulation => ")
print(fn)
print()
f = open(fn)
data = json.loads(f.read())

L = data["berry_field"]
sumnum = 0
bears = []
tourists = []
for i in data["active_bears"]:
    bears.append(Bear.Bear(i[0],i[1],i[2]))

for i in data["active_tourists"]:
    tourists.append(Tourist.Tourist(i[0],i[1]))



bf = BerryField.BerryField(data["berry_field"],bears,tourists)
bf.printAll()

print("Active bears:")
for i in bears:
    print(i.activeBears())

print()
print("Active Tourists:")
for i in tourists:
    print(i.activeTourist())

print()
bf.grow()

bf.printBerry()



